import assert from 'node:assert/strict';
import { readFileSync, writeFileSync } from 'node:fs';
import { Polar } from '@polar-sh/sdk';
// Volter World's biller (twin-world apps/billing/src/polar.ts and plans.ts) over the unchanged @polar-sh/sdk: the client,
// its catalog bootstrap, an org's billing read, the Team checkout, Manage billing and usage events, with their arguments.
const accessToken = process.env.POLAR_ACCESS_TOKEN;
if (!accessToken) throw new Error('billing: POLAR_ACCESS_TOKEN is not set');
const polar = new Polar({ accessToken, server: process.env.POLAR_SERVER === 'sandbox' ? 'sandbox' : 'production' });
const METERS = [
  { name: 'world_hours', event: 'world.hour', property: 'units' },
  { name: 'worlds_provisioned', event: 'world.provisioned', property: null },
  { name: 'twin_refreshes', event: 'twin.refresh', property: null },
  { name: 'world_pushes', event: 'world.push', property: null },
];
const TEAM = { polarProduct: 'Volter World Team', priceMonthly: 4900, trialDays: 14, overageCentsPerHour: 2, pitch: 'Worlds for every branch, pull request and teammate, deploying to the real vendors when you approve.' };
const ORG = 'org_acme';
const receiptFile = 'polar-records.json';
async function firstPage(page) {
  const direct = page.result?.items;
  if (direct) return direct;
  for await (const p of page) return p.result?.items ?? [];
  return [];
}
const statusOf = (error) => error?.statusCode ?? error?.status;

if (process.argv[2] === 'readback') {
  const saved = JSON.parse(readFileSync(receiptFile, 'utf8'));
  // the next boot's catalog bootstrap finds everything by name and makes nothing
  const meters = await firstPage(await polar.meters.list({ limit: 100 }));
  for (const m of METERS) assert.equal(meters.find((x) => x.name === m.name)?.id, saved.meters[m.name], `meter ${m.name} retained`);
  const products = await firstPage(await polar.products.list({ limit: 100 }));
  const team = products.find((p) => p.name === TEAM.polarProduct && !p.isArchived);
  assert.equal(team?.id, saved.product);
  assert.equal(team.recurringInterval, 'month');
  assert.equal(team.prices.length, 2);
  assert.equal(team.trialInterval, 'day');
  assert.equal(team.trialIntervalCount, 14);
  const state = await polar.customers.getStateExternal({ externalId: ORG });
  assert.equal(state.id, saved.customer);
  assert.equal(state.externalId, ORG);
  assert.deepEqual(state.activeSubscriptions, []);
  // events.list answers the page itself (EventsListResponseEventsList), not a page iterator
  const { items: events } = await polar.events.list({ externalCustomerId: ORG, limit: 100 });
  assert.equal(events.filter((e) => e.name === 'world.hour').length, 1, 'the retried hour is not counted twice');
  console.log(JSON.stringify({ retained: true, ...saved }));
} else {
  // ensureCatalog: the meters first, then the Team product with its fixed and metered prices and its trial
  const meters = await firstPage(await polar.meters.list({ limit: 100 }));
  const ids = {};
  for (const m of METERS) {
    let meter = meters.find((x) => x.name === m.name);
    if (!meter) {
      meter = await polar.meters.create({
        name: m.name,
        filter: { conjunction: 'and', clauses: [{ property: 'name', operator: 'eq', value: m.event }] },
        aggregation: m.property ? { func: 'sum', property: m.property } : { func: 'count' },
      });
    }
    ids[m.name] = meter.id;
  }
  assert.equal(Object.keys(ids).length, 4);
  const products = await firstPage(await polar.products.list({ limit: 100 }));
  let product = products.find((p) => p.name === TEAM.polarProduct && !p.isArchived);
  assert.equal(product, undefined, 'a new organization holds no Team product yet');
  product = await polar.products.create({
    name: TEAM.polarProduct, recurringInterval: 'month', description: TEAM.pitch,
    prices: [
      { amountType: 'fixed', priceAmount: TEAM.priceMonthly, priceCurrency: 'usd' },
      { amountType: 'metered_unit', unitAmount: TEAM.overageCentsPerHour, meterId: ids.world_hours },
    ],
    trialInterval: 'day', trialIntervalCount: TEAM.trialDays,
  });
  assert.equal(product.prices.length, 2);
  // orgBilling: an org with no customer yet reads as not found, which the biller takes as Free
  let missing;
  try { await polar.customers.getStateExternal({ externalId: ORG }); } catch (error) { missing = error; }
  assert.equal(statusOf(missing), 404, `an unknown org reads as not found: ${String(missing)}`);
  // checkoutFor: the Team checkout, the org as the customer, answering the hosted checkout's URL
  const checkout = await polar.checkouts.create({ products: [product.id], externalCustomerId: ORG, successUrl: 'https://world.volter.ai/acme/billing?checkout={CHECKOUT_ID}', customerEmail: 'ada@acme.dev', metadata: { org: ORG } });
  assert.match(checkout.url, /^https:\/\//);
  assert.equal(checkout.externalCustomerId, ORG);
  // portalFor's path for an org with no checkout yet: the customer made by its id, then the portal session
  const customer = await polar.customers.create({ email: 'ada@acme.dev', externalId: ORG });
  const session = await polar.customerSessions.create({ externalCustomerId: ORG, returnUrl: 'https://world.volter.ai/acme/billing' });
  assert.equal(session.customerId, customer.id);
  assert.match(session.customerPortalUrl, /^https:\/\//);
  // ingestUsage: an hour, then the same tick retried after a timeout, skipped as a duplicate
  const tick = [{ name: 'world.hour', externalCustomerId: ORG, externalId: `${ORG}:2026-01:hour-1`, metadata: { world: 'wld_main', units: 1 } }];
  const first = await polar.events.ingest({ events: tick });
  const again = await polar.events.ingest({ events: tick });
  assert.deepEqual([first.inserted, first.duplicates], [1, 0]);
  assert.deepEqual([again.inserted, again.duplicates], [0, 1]);
  const saved = { meters: ids, product: product.id, checkout: checkout.id, customer: customer.id };
  writeFileSync(receiptFile, JSON.stringify(saved) + '\n');
  console.log(JSON.stringify({ checkoutUrl: checkout.url, portal: session.customerPortalUrl, ...saved }));
}
